actions.script:
// a refusal (the Tools authorization, an external database here) is shown on the page, not dropped
capabilities = null
capabilitiesError = null
try {
    capabilities = ec.service.sync().name('org.moqui.dev.DatabaseServices.get#Capabilities').parameters({db}).call()
} catch (e) {
    capabilitiesError = String(e.message || e)
}
const errors = ec.message.getErrorsString()
if (errors) {
    capabilitiesError = errors
    capabilities = null
    ec.message.clearErrors()
}
const labels = {statementStats: 'Statement statistics', activity: 'Sessions and activity', cancel: 'Cancel a statement',
    terminate: 'End a session', lockWaits: 'Lock waits', tableSizes: 'Table sizes and row estimates',
    bloatExact: 'Exact table bloat', indexUsage: 'Index usage', indexOnline: 'Indexes built online',
    fkLightLock: 'Foreign keys with a light lock', maintenance: 'Vacuum, analyze and reindex',
    integrity: 'Integrity checks', settings: 'Server settings', settingsEdit: 'Editable settings', backups: 'Backups'}
const features = capabilities?.features || {}
featureList = Object.keys(labels).filter((name) => features[name] != null).map((name) => ({name,
    label: labels[name], available: !!features[name].available, reason: features[name].reason || ''}))
for (const name of Object.keys(features)) if (!labels[name]) featureList.push({name, label: name,
    available: !!features[name].available, reason: features[name].reason || ''})

const backendLabels = {'embedded-postgres': 'Embedded PostgreSQL', postgres: 'PostgreSQL', mysql: 'MySQL', mariadb: 'MariaDB'}
backendText = backendLabels[capabilities?.backend] || capabilities?.backend || selectedDatabase?.databaseConf || ''
startText = capabilities?.startTime == null ? '' : ec.l10n.format(basicConvert(capabilities.startTime, 'Timestamp'), null)
const seconds = capabilities?.uptimeSeconds
uptimeText = seconds == null ? '' : `${Math.floor(seconds / 86400)}d ${Math.floor(seconds % 86400 / 3600)}h ${Math.floor(seconds % 3600 / 60)}m`
const size = capabilities?.databaseSize
sizeText = size == null ? '' : size >= 1073741824 ? ec.l10n.format(size / 1073741824, '#,##0.0') + ' GiB'
    : ec.l10n.format(size / 1048576, '#,##0.0') + ' MiB'
isEmbedded = capabilities?.backend == 'embedded-postgres'
backupJob = isEmbedded ? ec.entity.find('moqui.service.job.ServiceJob').condition('jobName', 'backup_EmbeddedDatabase_daily').one() : null
// External databases (Connections): // whether the server offers external databases to this user (find#DatabaseConnections refuses with "Not available"
// on production or without DATABASE_EXTERNAL); asked only of a DATABASE_EXTERNAL holder
canExternal = false
if (ec.user.hasPermission('DATABASE_EXTERNAL')) {
    try { ec.service.sync().name('org.moqui.dev.DatabaseServices.find#DatabaseConnections').call(); canExternal = !ec.message.hasError() } catch (e) { canExternal = false }
    ec.message.clearErrors()
}
databaseRows = databaseList.map((database) => ({db: database.db, groups: database.label,
    databaseConf: database.databaseConf}))

// Monitor's numbers are shown to a reader of the telemetry only (the otel_metrics dataset, granted with System):
// to anyone else a report-embed says "Not available", so it is left out. list#Datasets leaves out, without an
// error, the datasets the user may not read.
monitorMetrics = false
try {
    monitorMetrics = (ec.service.sync().name('org.moqui.report.ReportServices.list#Datasets').call()?.datasets || [])
        .some((dataset) => dataset.id === 'otel_metrics')
} catch (e) { ec.logger.warn('The report datasets could not be listed: ' + String(e)) }
